import geoJson from "../data/territories.geo.json";

const geo = geoJson as unknown as Record<string, unknown>;

/** Territory id -> SVG path data (generated by scripts/generate-territories.mjs). */
export const TERRITORY_PATHS: Record<string, string> = Object.fromEntries(
  Object.entries(geo).filter(([k, v]) => !k.startsWith("_") && typeof v === "string") as [string, string][],
);
/** Region id -> outline path (mainland plus islands). */
export const REGION_PATHS = geo._regions as Record<string, string>;
/** Island-to-mainland (and island-to-island) links drawn as dashed lines. */
export const SEA_LINKS = geo._seaLinks as [string, string][];
